package main
import("encoding/json";"os";"fmt")
func main(){var inputs []map[string]any;if e:=json.Unmarshal([]byte(os.Args[1]),&inputs);e!=nil{panic(e)};out:=[]any{};for _,x:=range inputs{out=append(out,solve(x))};b,e:=json.Marshal(out);if e!=nil{panic(e)};fmt.Println(string(b))}

public.logic_test.go:
package main
import("testing";"encoding/json";"reflect")
func TestPublic(t *testing.T){var inputs []map[string]any;_ = json.Unmarshal([]byte(`[{"windows": []}, {"windows": [[2, 4]]}]`),&inputs);var expected []any;_ = json.Unmarshal([]byte(`[[], [[2, 4]]]`),&expected);for i,x:=range inputs{b,_:=json.Marshal(solve(x));var actual any;_ = json.Unmarshal(b,&actual);if !reflect.DeepEqual(actual,expected[i]){t.Fatalf("case %d: got %v want %v",i,actual,expected[i])}}}
